<script setup>
import {computed,watch} from 'vue';import {simulateCapacity} from '../sim/models/capacity.mjs';import {capacityPresets} from '../sim/scenarios.mjs';import {useLabSession} from '../sim/session.mjs';
const props=defineProps({focus:{type:String,default:'workload'}});const s=useLabSession('scale');watch(()=>s.preset,()=>{s.cache=false;s.cdn=false;s.rps=1000;s.replicas=1});const scenario=computed(()=>capacityPresets[s.preset]);const result=computed(()=>simulateCapacity({preset:s.preset,requestsPerSec:s.rps,cache:s.cache,cdn:s.cdn,replicas:s.replicas,cacheHit:scenario.value.cacheHit,objectKB:scenario.value.objectKB}));
function pct(v){return Math.round(v*100)}function label(id){return {app:'App',db:'Database',cache:'Cache',cdn:'CDN',origin:'Object Storage'}[id]||id}
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>情境</span><div class="sim-segment"><button v-for="(scenarioOption,id) in capacityPresets" :key="id" :aria-pressed="s.preset===id" @click="s.preset=id">{{scenarioOption.label}}</button></div><small>{{scenario.description}}</small></div><div><span>流量：{{s.rps.toLocaleString()}} req/s</span><input v-model.number="s.rps" type="range" min="1000" max="100000" step="1000" aria-label="每秒請求數"></div><div v-if="props.focus==='intervention'||props.focus==='transfer'"><span>改架構</span><div class="sim-segment"><button v-if="s.preset!=='video'" :aria-pressed="s.cache" @click="s.cache=!s.cache">Cache {{s.cache?'ON':'OFF'}}</button><button v-if="s.preset==='video'" :aria-pressed="s.cdn" @click="s.cdn=!s.cdn">CDN {{s.cdn?'ON':'OFF'}}</button><button v-if="s.preset!=='video'" @click="s.replicas=Math.min(4,s.replicas+1)">App × {{s.replicas}}</button></div></div></div><div class="sim-system sim-system-nodes"><template v-for="(n,i) in result.nodes" :key="n.id"><div v-if="i" class="sim-arrow">→</div><div :class="['sim-node',{'is-critical':n.status==='critical','is-warning':n.status==='warning'}]"><b>{{label(n.id)}}</b><span>送入 {{n.incoming.toLocaleString()}} QPS · 負載 {{pct(n.utilization)}}%</span><div class="sim-util"><i :style="{width:Math.min(100,pct(n.utilization))+'%'}"></i></div></div></template></div><div class="sim-metrics"><div><span>整體完成量（Throughput）</span><strong>{{result.throughput.toLocaleString()}} /s</strong></div><div><span>估計路徑延遲</span><strong>{{Math.round(result.totalLatency)}} ms</strong></div><div><span>Origin bandwidth</span><strong>{{Math.round(result.bandwidthMbps)}} Mbps</strong></div><div :class="{'is-bad':result.bottlenecks.length}"><span>Bottleneck</span><strong>{{result.bottlenecks.length?result.bottlenecks.map(label).join('、'):'目前沒有'}}</strong></div></div><div class="sim-consequence"><strong>「送進去」和「做得完」是兩個數字</strong><p>Node 上的 QPS 是送到該元件的需求量，不代表全部成功完成。下方 Throughput 才是這個教學模型估計的整體完成量。超過 capacity 時，兩者會分開。</p></div></section></template>